function lotka_volterra()
    alpha = 1.1; beta = 0.4; delta = 0.1; gamma = 0.4;
    f = @(t, y) [alpha*y(1) - beta*y(1)*y(2);
                 delta*y(1)*y(2) - gamma*y(2)];
    tspan = [0 50];
    for y0 = [5 10; 10 5; 15 15]'
        [t, y] = ode45(f, tspan, y0);
        plot(y(:,1), y(:,2)); hold on;
    end
    xlabel('Ov'); ylabel('Yırtıcı'); grid on;
end

template <typename F>
std::vector<double> rk4(F f, double y0, double t0, double t1, int steps) {
    double h = (t1 - t0) / steps;
    std::vector<double> y(steps + 1);
    y[0] = y0;
    double t = t0;
    for (int i = 0; i < steps; ++i) {
        double k1 = f(t, y[i]);
        double k2 = f(t + h/2, y[i] + h/2 * k1);
        double k3 = f(t + h/2, y[i] + h/2 * k2);
        double k4 = f(t + h, y[i] + h * k3);
        y[i+1] = y[i] + (h/6.0) * (k1 + 2*k2 + 2*k3 + k4);
        t += h;
    }
    return y;
}
